import {tile} from './horizons.js';
export function terrainLighting(M,time){const world=`varying vec3 vAuralisWorld;\n`,vertex=`\n vec4 aw=vec4(transformed,1.0);\n #ifdef USE_INSTANCING\n aw=instanceMatrix*aw;\n #endif\n vAuralisWorld=(modelMatrix*aw).xyz;\n`,noise=`float ah(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}float an(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(ah(i),ah(i+vec2(1,0)),f.x),mix(ah(i+vec2(0,1)),ah(i+vec2(1,1)),f.x),f.y);}\n`;
 for(const name of['grass','sand','snow','water']){const mat=M[name];mat.onBeforeCompile=shader=>{shader.uniforms.auralisTime=time;shader.vertexShader=world+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>','#include <project_vertex>'+vertex);shader.fragmentShader=world+'uniform float auralisTime;\n'+noise+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#ifdef USE_MAP\n diffuseColor*=texture2D(map,vAuralisWorld.xz*.21);\n #endif`);const effect=name==='water'?`float wave=sin(vAuralisWorld.x*2.2+auralisTime*.8+an(vAuralisWorld.xz*.4)*3.0)*sin(vAuralisWorld.z*3.6-auralisTime*.7);diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.18,.53,.57),.24)+vec3(.045,.07,.06)*pow(max(0.0,wave),9.0);`:name==='grass'?`float terrainBlend=an(vAuralisWorld.xz*.13)*.65+an(vAuralisWorld.xz*.61)*.35;diffuseColor.rgb*=mix(vec3(.84,.9,.72),vec3(1.05,1.08,.94),terrainBlend);`:`diffuseColor.rgb*=.91+an(vAuralisWorld.xz*.3)*.16;`;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\n'+effect);};mat.customProgramCacheKey=()=>name+'-frontier-painted-v11';}
}
export function drawWorldEffects(r,B,state){if(r.layer)return;const m=r.map,M=r.M,time=r.time,visible=(x,y)=>!!m.sight?.[Math.floor(y)*m.size+Math.floor(x)]&&r.onScreen(x,y,80),put=(shape,mat,x,y,z,sx,sy,sz,yaw=0)=>r.put(B,shape,mat,x-r.origin,y,z-r.origin,sx,sy,sz,yaw);
 let workers=0;for(const u of m.units){if(workers>=16||u.hp<=0||u.embarked||u.inTransit||u.depth||!visible(u.x,u.y))continue;const work=['gather','dig','construct','upgrade','project','operate','survey','study','infrastructure'].includes(u.order.kind)&&!u.walking;if(!work)continue;workers++;const phase=(time*1.3+u.x*.31)%1,h=tile(m,u.x,u.y).h*.3;for(let k=0;k<2;k++){const f=(phase+k*.42)%1,s=.035+f*.08;put('ball',u.gatherResource==='wood'?M.cutwood:M.dust,u.x+.25+Math.sin(u.x+k)*f*.24,h+.08+f*.4,u.y+.22+Math.cos(u.y+k)*f*.24,s,s*.7,s);}}
 let chimneys=0;for(const b of m.buildings){if(chimneys>=10||b.hp<=0||b.progress<1||!visible(b.x,b.y))continue;const hot=b.type==='reactor'?m.stock.coal>0:b.type==='camp'?b.tier===0:['smithy','foundry','bakery','workshop'].includes(b.type)&&b.serviceActive;if(!hot)continue;chimneys++;const h=tile(m,b.x,b.y).h*.3,base=b.type==='camp'?.3:1.8;for(let i=0;i<3;i++){const phase=(time*.24+i*.31+b.x*.17)%1,size=.07+phase*.17;put('ball',M.smoke,b.x+.7+phase*.25,h+base+phase*.7,b.y+.6,size,size*.7,size);}}
 const now=performance.now();for(const s of r.shots){if(!visible(s.x,s.y)&&!visible(s.tx,s.ty))continue;const f=(now-s.at)/600;if(f<0||f>1)continue;const heavy=['bulwark','missile','gunboat','jeep'].includes(s.kind),arrow=['archer','spearman'].includes(s.kind),from=tile(m,s.x,s.y)?.h*.3||0,to=tile(m,s.tx,s.ty)?.h*.3||0;
  if(f<.58){const p=f/.58,x=s.x+(s.tx-s.x)*p,z=s.y+(s.ty-s.y)*p,y=from+(to-from)*p+.55+(arrow?Math.sin(p*Math.PI)*.6:0);if(arrow){put('box',M.darkwood,x,y,z,.035,.035,.33,Math.atan2(s.tx-s.x,s.ty-s.y));}else{put('ball',heavy?M.fire:M.glow,x,y,z,heavy?.09:.055,heavy?.09:.055,heavy?.09:.055);}if(!arrow&&f<.12)put('ball',M.fire,s.x,from+.62,s.y,.16*(1-f*5),.13,.16*(1-f*5));}
  else{const p=(f-.58)/.42;for(let k=0;k<(heavy?7:3);k++){const a=k*2.4+s.tx,dist=p*(heavy?.7:.3),size=(1-p)*(heavy?.09:.045);put('ball',k%3===0?M.fire:heavy?M.smoke:M.dust,s.tx+Math.cos(a)*dist,to+.12+Math.sin(p*Math.PI)*.45,s.ty+Math.sin(a)*dist,size,size,size);}}
 }
}
